#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node *next;
} Node;

void detect_cycle(Node *head, int n) {
    if (head == NULL) {
        printf("NO_CYCLE\n");
        return;
    }

    Node *slow = head;
    Node *fast = head;
    int has_cycle = 0;

    while (fast != NULL && fast->next != NULL) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            has_cycle = 1;
            break;
        }
    }

    if (!has_cycle) {
        printf("NO_CYCLE\n");
        return;
    }

    // Find cycle start
    slow = head;
    int start_index = 0;
    while (slow != fast) {
        slow = slow->next;
        fast = fast->next;
        start_index++;
    }

    // Find cycle length
    int cycle_len = 1;
    Node *curr = slow->next;
    while (curr != slow) {
        curr = curr->next;
        cycle_len++;
    }

    printf("CYCLE_DETECTED START_INDEX: %d LENGTH: %d\n", start_index, cycle_len);
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    if (n == 0) {
        printf("NO_CYCLE\n");
        return 0;
    }

    Node **nodes = (Node **)malloc(n * sizeof(Node *));
    for (int i = 0; i < n; i++) {
        int val;
        scanf("%d", &val);
        nodes[i] = (Node *)malloc(sizeof(Node));
        nodes[i]->data = val;
        nodes[i]->next = NULL;
        if (i > 0) {
            nodes[i - 1]->next = nodes[i];
        }
    }

    int pos;
    scanf("%d", &pos);
    if (pos >= 0 && pos < n) {
        nodes[n - 1]->next = nodes[pos];
    }

    detect_cycle(nodes[0], n);

    // Clean up
    for (int i = 0; i < n; i++) {
        free(nodes[i]);
    }
    free(nodes);
    return 0;
}

