    struct Node *next;
} Node;

int get_length(Node *head) {
    int len = 0;
    while (head != NULL) {
        len++;
        head = head->next;
    }
    return len;
}

void find_intersection(Node *headA, Node *headB) {
    if (headA == NULL || headB == NULL) {
        printf("NO_INTERSECTION\n");
        return;
    }

    int lenA = get_length(headA);
    int lenB = get_length(headB);

    Node *currA = headA;
    Node *currB = headB;

    if (lenA > lenB) {
        for (int i = 0; i < lenA - lenB; i++) {
            currA = currA->next;
        }
    } else {
        for (int i = 0; i < lenB - lenA; i++) {
            currB = currB->next;
        }
    }

    while (currA != NULL && currB != NULL) {
        if (currA == currB) {
            printf("INTERSECTION_VAL: %d\n", currA->data);
            return;
        }
        currA = currA->next;
        currB = currB->next;
    }
    printf("NO_INTERSECTION\n");
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    Node *headA = NULL, *tailA = NULL;
    for (int i = 0; i < n; i++) {
