#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct DNode {
    int data;
    struct DNode *prev;
    struct DNode *next;
} DNode;

typedef struct {
    DNode *head;
    DNode *tail;
} DoublyLinkedList;

void dll_push_front(DoublyLinkedList *list, int val) {
    DNode *node = (DNode *)malloc(sizeof(DNode));
    node->data = val;
    node->prev = NULL;
    node->next = list->head;
    if (list->head != NULL) {
        list->head->prev = node;
    } else {
        list->tail = node;
    }
    list->head = node;
}

void dll_push_back(DoublyLinkedList *list, int val) {
    DNode *node = (DNode *)malloc(sizeof(DNode));
    node->data = val;
    node->next = NULL;
    node->prev = list->tail;
    if (list->tail != NULL) {
        list->tail->next = node;
    } else {
        list->head = node;
    }
    list->tail = node;
}

void dll_delete(DoublyLinkedList *list, int val) {
    DNode *curr = list->head;
    while (curr != NULL) {
        if (curr->data == val) {
            if (curr->prev != NULL) {
                curr->prev->next = curr->next;
            } else {
                list->head = curr->next;
            }
            if (curr->next != NULL) {
                curr->next->prev = curr->prev;
            } else {
                list->tail = curr->prev;
            }
            free(curr);
            printf("DELETED\n");
            return;
        }
        curr = curr->next;
    }
    printf("NOT_FOUND\n");
}

void dll_print_forward(DoublyLinkedList *list) {
    if (list->head == NULL) {
        printf("EMPTY\n");
        return;
    }
    DNode *curr = list->head;
    while (curr != NULL) {
        printf("%d <-> ", curr->data);
        curr = curr->next;
    }
    printf("NULL\n");
}

void dll_print_backward(DoublyLinkedList *list) {
    if (list->tail == NULL) {
        printf("EMPTY\n");
        return;
    }
    DNode *curr = list->tail;
    while (curr != NULL) {
        printf("%d <-> ", curr->data);
        curr = curr->prev;
    }
    printf("NULL\n");
}

void dll_free(DoublyLinkedList *list) {
    DNode *curr = list->head;
    while (curr != NULL) {
        DNode *temp = curr->next;
        free(curr);
        curr = temp;
    }
    list->head = list->tail = NULL;
}

