#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int id;
    struct Node *next;
} Node;

void solve_josephus(int n, int k) {
    if (n <= 0) return;

    Node *head = (Node *)malloc(sizeof(Node));
    head->id = 1;
    head->next = NULL;

    Node *prev = head;
    for (int i = 2; i <= n; i++) {
        Node *node = (Node *)malloc(sizeof(Node));
        node->id = i;
        node->next = NULL;
        prev->next = node;
        prev = node;
    }
    prev->next = head; // Make circular

    printf("ELIMINATED: ");
    Node *curr = head;
    Node *p = prev;

    for (int count = 1; count < n; count++) {
        for (int i = 0; i < k - 1; i++) {
            p = curr;
            curr = curr->next;
        }
        printf("%d%s", curr->id, (count == n - 1) ? "" : " ");
        p->next = curr->next;
        Node *temp = curr;
        curr = curr->next;
        free(temp);
    }
    printf("\nSURVIVOR: %d\n", curr->id);
    free(curr);
}

