typedef struct Node {
    int data;
    struct Node *next;
} Node;

Node* add_two_numbers(Node *l1, Node *l2) {
    Node dummy;
    dummy.next = NULL;
    Node *tail = &dummy;
    int carry = 0;

    while (l1 != NULL || l2 != NULL || carry > 0) {
        int sum = carry;
        if (l1 != NULL) {
            sum += l1->data;
            l1 = l1->next;
        }
        if (l2 != NULL) {
            sum += l2->data;
            l2 = l2->next;
        }
        carry = sum / 10;

        Node *node = (Node *)malloc(sizeof(Node));
        node->data = sum % 10;
        node->next = NULL;
        tail->next = node;
        tail = node;
    }

    return dummy.next;
}

