#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct MNode {
    int val;
    struct MNode *next;
    struct MNode *child;
} MNode;

MNode* find_node(MNode *root, int val) {
    if (!root) return NULL;
    if (root->val == val) return root;
    MNode *res = find_node(root->child, val);
    if (res) return res;
    return find_node(root->next, val);
}

MNode* flatten_dfs(MNode *head) {
    if (!head) return NULL;
    MNode *curr = head;
    while (curr != NULL) {
        if (curr->child != NULL) {
            MNode *next_node = curr->next;
            MNode *child_head = curr->child;
            curr->child = NULL;

            MNode *flat_child = flatten_dfs(child_head);
            curr->next = flat_child;

            MNode *tail = flat_child;
            while (tail->next != NULL) {
                tail = tail->next;
            }
            tail->next = next_node;
            curr = next_node;
        } else {
            curr = curr->next;
        }
    }
    return head;
}

void print_list(MNode *head) {
    if (!head) {
        printf("EMPTY\n");
        return;
    }
    MNode *curr = head;
    while (curr != NULL) {
        printf("%d -> ", curr->val);
        curr = curr->next;
    }
    printf("NULL\n");
}

void free_flat_list(MNode *head) {
    MNode *curr = head;
    while (curr != NULL) {
        MNode *temp = curr->next;
        free(curr);
        curr = temp;
    }
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    MNode *head = NULL, *tail = NULL;
    char op[16];

    for (int i = 0; i < n; i++) {
        if (scanf("%s", op) != 1) break;
        if (strcmp(op, "APPEND") == 0) {
            int val; scanf("%d", &val);
            MNode *node = (MNode *)malloc(sizeof(MNode));
            node->val = val; node->next = NULL; node->child = NULL;
            if (!head) head = tail = node;
            else { tail->next = node; tail = node; }
        } else if (strcmp(op, "CHILD") == 0) {
            int pval, cval; scanf("%d %d", &pval, &cval);
            MNode *parent = find_node(head, pval);
            if (parent) {
                MNode *cnode = (MNode *)malloc(sizeof(MNode));
                cnode->val = cval; cnode->next = NULL; cnode->child = NULL;
                if (!parent->child) {
                    parent->child = cnode;
                } else {
                    MNode *ctail = parent->child;
                    while (ctail->next) ctail = ctail->next;
                    ctail->next = cnode;
                }
            }
        } else if (strcmp(op, "FLATTEN") == 0) {
            head = flatten_dfs(head);
            print_list(head);
        }
    }

    free_flat_list(head);
    return 0;
}
